validator:
function validate(input) {
  const [{ df1 = [], df2 = [] }] = input;
  for (const [label, rows] of [['df1', df1], ['df2', df2]]) {
    for (const row of rows) if (row.some(value => value === null)) return `${label} cannot contain null values.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = ['Mason', 'Ava', 'Taylor', 'Georgia', 'Leo', 'Alex'];
  const table = () => {
    const count = size === 'small' ? Math.floor(rand() * 9) : 1500 + Math.floor(rand() * 500);
    const rows = [];
    for (let i = 0; i < count; i++) {
      const id = size === 'small' ? 1 + Math.floor(rand() * 6) : 1 + Math.floor(rand() * 3000);
      rows.push([id, pick(names), 5 + Math.floor(rand() * (size === 'small' ? 4 : 14))]);
    }
    return rows;
  };
  return [{ df1: table(), df2: table() }];
}
